const milestones = [];                       // [{ from: Temporal.PlainDate, value }], sorted

export function valueAt(when) {
  let lo = 0, hi = milestones.length;        // first index whose from > when
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (Temporal.PlainDate.compare(milestones[mid].from, when) <= 0) lo = mid + 1; else hi = mid;
  }
  if (lo === 0) throw new RangeError(`no value effective on ${when}`);
  return milestones[lo - 1].value;
}
export const current = () => valueAt(Temporal.Now.plainDateISO());
